-- rerun of Q11 (regex fixed)
-- donors of the 19 (Schedule A, lump rows dropped) found in FEC individual contributions: key = 5-digit zip + surname + first initial. which FEC committees do they give to?
WITH g AS (SELECT column1 EIN FROM VALUES ('821194581'),('822366231'),('815214552'),('843153271'),('822315009'),('834686848'),('843763411'),('853307234'),('472041040'),('273594732'),('843763242'),
  ('921706849'),('922354897'),('861386683'),('843763606'),('922452599'),('923489519'),('854325630'),('923489713')),
s AS (SELECT DISTINCT LEFT(CONTRIBUTOR_ZIP,5) z,
   IFF(CONTRIBUTOR_NAME LIKE '%,%', TRIM(SPLIT_PART(UPPER(CONTRIBUTOR_NAME),',',1)), REGEXP_SUBSTR(TRIM(UPPER(CONTRIBUTOR_NAME)),'[A-Z]+$')) ln,
   LEFT(IFF(CONTRIBUTOR_NAME LIKE '%,%', TRIM(SPLIT_PART(UPPER(CONTRIBUTOR_NAME),',',2)), TRIM(UPPER(CONTRIBUTOR_NAME))),1) fi
  FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_IRS527_SCHEDULE_A_CONTRIBUTIONS WHERE EIN IN (SELECT EIN FROM g)
   AND NOT REGEXP_LIKE(UPPER(CONTRIBUTOR_NAME),'.*(AGGREGATE|UNITEMIZED|TOTAL|BELOW THRESHOLD|VARIOUS|ITEMIZED|WITHHELD).*')),
f AS (SELECT CMTE_ID, LEFT(ZIP_CODE,5) z, TRIM(SPLIT_PART(DONOR_NAME,',',1)) ln, LEFT(TRIM(SPLIT_PART(DONOR_NAME,',',2)),1) fi, TRANSACTION_AMT a
  FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_FEC_INDIV_CONTRIBUTIONS WHERE COALESCE(MEMO_CD,'')<>'X' AND LEFT(ZIP_CODE,5) IN (SELECT z FROM s)),
m AS (SELECT f.* FROM f JOIN s ON s.z=f.z AND s.ln=f.ln AND s.fi=f.fi)
SELECT 'summary' k, NULL CMTE_ID, (SELECT COUNT(*) FROM s) keys_19, COUNT(DISTINCT z||ln||fi) matched_keys, COUNT(*) fec_rows, ROUND(SUM(a)/1e6,2) fec_m, NULL nm FROM m
UNION ALL
SELECT * FROM (SELECT 'cmte', m.CMTE_ID, NULL, COUNT(DISTINCT z||ln||fi), COUNT(*), ROUND(SUM(a)/1e6,3), MAX(d.CMTE_NM)
  FROM m LEFT JOIN LIBRARY_MARTS.FINANCE.FINANCE__FED_FEC_COMMITTEES d ON d.CMTE_ID=m.CMTE_ID GROUP BY m.CMTE_ID ORDER BY 4 DESC LIMIT 45)
ORDER BY k DESC, matched_keys DESC
